<script lang="ts">
 import {invalidateAll} from '$app/navigation';import DataTable from './DataTable.svelte';let {model,t,lang,timezone}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string;lang:string;timezone:string}=$props();let connection=$state(''),bottling=$state(''),ack=$state(false),busy=$state(false),message=$state('');
 async function submit(action:string){busy=true;try{const res=await fetch('/api/connections/deliver',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(action==='run'?{action}:{action,connection_id:connection,bottling_id:bottling,confirmed:ack})});message=res.ok?t('saved'):t((await res.json()).message);if(res.ok)await invalidateAll();}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
</script>
<section class="card"><h2>{t('deliveries')}</h2><p class="muted">{t('contractReceiptHint')}</p><form onsubmit={(e)=>{e.preventDefault();submit('queue');}}><div class="grid"><label>{t('connections')}<select required bind:value={connection}><option value="">—</option>{#each model.connections.filter(c=>c.adapter==='contract-api'&&c.enabled&&c.configuration.contract?.outbound?.confirmed) as c}<option value={c.id}>{c.name}</option>{/each}</select></label><label>{t('bottling')}<select required bind:value={bottling}><option value="">—</option>{#each model.bottlings as b}<option value={b.id}>{b.code} · {b.bottle_count}</option>{/each}</select></label></div><label class="check"><input type="checkbox" required bind:checked={ack} />{t('queueDelivery')}</label><button disabled={busy||!ack}>{t('queueDelivery')}</button></form><button disabled={busy} onclick={()=>submit('run')}>{t('runDeliveries')}</button><DataTable rows={model.deliveries??[]} columns={['bottling_id','connection_id','status','attempts','external_id','last_error','updated_at']} {t} {lang} {timezone} /><p role="status">{message}</p></section>
<style>.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:20px 0}.check{display:flex;align-items:center;margin:20px 0}.check input{width:18px;height:18px}button{margin-bottom:20px}</style>
